export function packDocumentName(pack) {
  return pack?.documentName ?? pack?.metadata?.type ?? null;
}

export function compendiumSearchPacks(typeFilter) {
  return [...game.packs].filter((pack) => {
    const docName = packDocumentName(pack);
    if (!docName || !typeFilter.has(docName)) return false;
    if (!game.user?.isGM && pack.private) return false;
    return true;
  });
}

export function parseCompendiumSearchQuery(query) {
  const raw = String(query ?? "").trim();
  if (raw.length < 2) return null;
  const cleaned = foundry?.applications?.ux?.SearchFilter?.cleanQuery
    ? foundry.applications.ux.SearchFilter.cleanQuery(raw).toLowerCase()
    : raw.toLowerCase();
  const splitQuery = cleaned.split(/\s+/).map((part) => part.trim()).filter(Boolean);
  return splitQuery.length > 0 ? splitQuery : null;
}

export function compendiumNameMatchesQuery(name, keywords, splitQuery, term) {
  if (typeof term?.match === "function") {
    return splitQuery.every((part) => term.match(part));
  }
  const haystack = foundry?.applications?.ux?.SearchFilter?.cleanQuery
    ? foundry.applications.ux.SearchFilter.cleanQuery(String(name ?? "")).toLowerCase()
    : String(name ?? "").toLowerCase();
  const keywordList = Array.isArray(keywords)
    ? keywords.map((keyword) => String(keyword).toLowerCase())
    : [];
  return splitQuery.every((part) =>
    haystack.includes(part) || keywordList.some((keyword) => keyword.includes(part))
  );
}

function* iterateCompendiumIndex(index) {
  if (!index) return;
  if (typeof index.values === "function") {
    yield* index.values();
    return;
  }
  if (typeof index[Symbol.iterator] === "function") {
    for (const value of index) {
      if (Array.isArray(value) && value.length === 2 && value[1] && typeof value[1] === "object") {
        yield value[1];
      } else {
        yield value;
      }
    }
    return;
  }
  yield* Object.values(index);
}

export function resolveCompendiumEntryUuid(pack, entry) {
  if (entry?.uuid) return String(entry.uuid);
  const id = entry?._id;
  if (id && typeof pack?.getUuid === "function") {
    return pack.getUuid(id);
  }
  if (id && pack?.collection) {
    const docName = packDocumentName(pack);
    return docName
      ? `Compendium.${pack.collection}.${docName}.${id}`
      : `Compendium.${pack.collection}.${id}`;
  }
  return null;
}

export function compendiumPackDescription(pack) {
  const meta = pack?.metadata ?? {};
  const packLabel = meta.label ?? pack?.collection ?? "";
  const scope = meta.packageName ?? meta.package ?? "";
  return scope && packLabel ? `${scope} - ${packLabel}` : (packLabel || scope || null);
}

/** Human label for a trait key family: "skills:ins" -> "Skills". */
export const TRAIT_FAMILY_LABELS = {
  skills: "Skills",
  languages: "Languages",
  tool: "Tools",
  weapon: "Weapons",
  armor: "Armor",
  saves: "Saves",
  abilities: "Abilities"
};

export function traitFamilyLabel(keys) {
  for (const key of keys) {
    const family = String(key).split(":")[0];
    if (TRAIT_FAMILY_LABELS[family]) return TRAIT_FAMILY_LABELS[family];
  }
  return null;
}

/**
 * What a compendium entry actually grants, read straight off its advancement.
 *
 * Written for the eye rather than for machinery: a player picking a background
 * cannot open the item to see that its "Tool Proficiencies" is an empty block,
 * or that a "choose 2 languages" has nothing to choose from — both of which
 * happen to entries imported from D&D Beyond. Shown in the list, a `0` or an
 * empty pool is something a player can notice and report.
 *
 * @param {object[]} advancement   Raw advancement data from the pack index
 */
export function summarizeAdvancementTraits(advancement) {
  const out = [];
  try {
    for (const entry of asIndexList(advancement)) {
      if (entry?.type !== "Trait") continue;
      const config = entry.configuration ?? {};
      const grants = asIndexList(config.grants);
      const choices = asIndexList(config.choices);
      let count = grants.length;
      // A choice with an empty pool promises a pick it cannot deliver.
      let emptyPool = false;
      const poolKeys = [];
      for (const choice of choices) {
        count += Number(choice?.count) || 0;
        const pool = asIndexList(choice?.pool);
        poolKeys.push(...pool);
        if (!pool.length) emptyPool = true;
      }
      out.push({
        // The stored title survives an empty block, where the keys cannot tell
        // us what the block was meant to be about.
        label: entry.title || traitFamilyLabel([...grants, ...poolKeys]) || "Traits",
        count,
        // Two different things, and conflating them cost a round of confusion.
        //
        // "empty": a block with nothing in it at all. Importers emit these for
        // categories a background does not use, so it is noise - worth showing,
        // because it is what makes the wizard offer a step with no choices, but
        // not worth alarming anyone about.
        //
        // "pool": a block that promises N picks from a list that is empty. That
        // is a real loss: the entry looks complete and delivers nothing.
        issue: count === 0 ? "empty" : (emptyPool ? "pool" : null)
      });
    }
  } catch (err) {
    // A summary is a nicety; a picker that fails to list anything is not.
    console.warn(`[${MODULE_ID}] advancement summary failed`, err);
    return [];
  }
  return out;
}

/**
 * A pack index is not the document it came from.
 *
 * Foundry expands the requested fields into the index entry, and an array can
 * arrive as an object keyed by position — `{0: …, 1: …}` — while a Set can
 * arrive as either. Anything read out of an index has to survive both shapes.
 */
export function asIndexList(value) {
  if (Array.isArray(value)) return value;
  if (value instanceof Set) return [...value];
  if (value && typeof value === "object") return Object.values(value);
  return [];
}

export function pushCompendiumSearchResult(results, seen, max, entry) {
  if (results.length >= max || !entry?.uuid || seen.has(entry.uuid)) return;
  seen.add(entry.uuid);
  results.push(entry);
}

/** Label shown in the corner of a world (non-compendium) item's result row. */
export function worldItemsLabel() {
  const lang = String(game.i18n?.lang ?? "en").slice(0, 2).toLowerCase();
  if (lang === "ru") return "Мир (хоумбрю)";
  if (lang === "es") return "Mundo (casero)";
  return "World (homebrew)";
}

/**
 * Whether the requester may see one world item. With a user, it is their
 * OBSERVER permission; without one (an internal call), only items shared with
 * everyone by default, so a GM's private drafts never leak.
 */
export function worldItemVisibleTo(item, user) {
  try {
    if (user) return item.testUserPermission(user, "OBSERVER");
    const def = item.ownership?.default ?? 0;
    return def >= CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER;
  } catch (err) {
    return false;
  }
}

/** Adds matching world items (game.items) to the search results in place. */
export function collectWorldItemResults(results, seen, max, { subtypeFilter, splitQuery, user }) {
  for (const item of game.items ?? []) {
    if (results.length >= max) break;
    const name = String(item?.name ?? "");
    if (!name) continue;
    if (subtypeFilter && !subtypeFilter.has(String(item.type ?? "").toLowerCase())) continue;
    if (splitQuery && !compendiumNameMatchesQuery(name, null, splitQuery)) continue;
    if (!worldItemVisibleTo(item, user)) continue;
    pushCompendiumSearchResult(results, seen, max, {
      uuid: item.uuid,
      name,
      documentName: "Item",
      pack: worldItemsLabel(),
      source: "world",
      subtype: item.type ? String(item.type) : null,
      img: routeAssetPath(item.img),
      traits: summarizeAdvancementTraits(item.system?.advancement)
    });
  }
}

/**
 * Search compendium packs by name using Foundry's built-in pack index.
 */
/**
 * @param {string|null} query   null browses: every entry of the requested type,
 *                              which is what a race or class picker wants before
 *                              the player has typed anything.
 */
export async function nativeCompendiumSearch(query, types, subtypes, limit, user = null) {
  const splitQuery = query === null ? null : parseCompendiumSearchQuery(query);
  if (query !== null && !splitQuery) return { results: [] };
  const typeFilter = Array.isArray(types) && types.length > 0 ? new Set(types) : new Set(["Item"]);
  const subtypeFilter = Array.isArray(subtypes) && subtypes.length > 0
    ? new Set(subtypes.map((s) => String(s).toLowerCase()))
    : null;
  const max = Math.max(1, Math.min(Number(limit) || 30, 100));

  const results = [];
  const seen = new Set();

  // World items are a source too: content authored in this world — including the
  // homebrew backgrounds/races the mobile wizards create — lives in game.items,
  // not in a compendium pack, so the pack walk below never finds it. Listed
  // first so a player's own homebrew shows above the compendium bulk. Only items
  // the requester may see are offered (the wizards make them OBSERVER-visible).
  if (typeFilter.has("Item")) {
    collectWorldItemResults(results, seen, max, { subtypeFilter, splitQuery, user });
  }

  const packs = compendiumSearchPacks(typeFilter);

  for (const pack of packs) {
    if (results.length >= max) break;
    let index;
    try {
      // `system.advancement` rides along in the index, so the summary below
      // costs no document loads — the index is built once per pack and cached.
      index = await pack.getIndex({
        fields: ["uuid", "type", "img", "name", "system.advancement"]
      });
    } catch (err) {
      console.warn(`[${MODULE_ID}] nativeCompendiumSearch getIndex failed for ${pack.collection}`, err);
      continue;
    }

    const packDescription = compendiumPackDescription(pack);
    const documentName = packDocumentName(pack);

    for (const entry of iterateCompendiumIndex(index)) {
      if (results.length >= max) break;
      const name = String(entry?.name ?? "");
      if (!name) continue;
      if (splitQuery && !compendiumNameMatchesQuery(name, null, splitQuery)) continue;
      if (subtypeFilter) {
        const rawSubtype = entry?.type;
        if (!rawSubtype || !subtypeFilter.has(String(rawSubtype).toLowerCase())) continue;
      }
      const uuid = resolveCompendiumEntryUuid(pack, entry);
      if (!uuid) continue;
      pushCompendiumSearchResult(results, seen, max, {
        uuid,
        name,
        documentName,
        pack: packDescription,
        // Which package the entry came from, for the corner of the row: two
        // compendiums can both hold an "Acolyte" and only one of them be whole.
        source: pack.metadata?.packageName ?? pack.metadata?.package ?? null,
        subtype: entry.type ? String(entry.type) : null,
        img: routeAssetPath(entry.img),
        traits: summarizeAdvancementTraits(entry.system?.advancement)
      });
    }
  }

  console.log(
    `[${MODULE_ID}] compendium.search via native index: query="${splitQuery ? splitQuery.join(" ") : "(browse)"}"` +
    ` types=[${[...typeFilter].join(",")}]` +
    (subtypeFilter ? ` subtypes=[${[...subtypeFilter].join(",")}]` : "") +
    ` → ${results.length} hits (${packs.length} packs)`
  );
  // Prefer weapons over DDB consumable/ammo stubs with the same name.
  results.sort((a, b) => {
    const rank = (s) => {
      const t = String(s?.subtype ?? "").toLowerCase();
      if (t === "weapon") return 0;
      if (t === "equipment") return 1;
      if (t === "consumable") return 3;
      return 2;
    };
    const r = rank(a) - rank(b);
    if (r !== 0) return r;
    const aw = (() => {
      const s = String(a.pack ?? "").toLowerCase();
      return s.includes("world") || s.includes("ddb") ? 1 : 0;
    })();
    const bw = (() => {
      const s = String(b.pack ?? "").toLowerCase();
      return s.includes("world") || s.includes("ddb") ? 1 : 0;
    })();
    return aw - bw;
  });
  return { results };
}

export function resolveCompendiumUuidFromSpotlightTerm(term) {
  const data = term?.data ?? {};
  if (data.uuid) return String(data.uuid);

  const id = data._id;
  const collection = data.collection ?? data.pack ?? data.packName;
  if (id && collection) {
    const pack = game.packs.get(String(collection));
    if (pack) return resolveCompendiumEntryUuid(pack, data);
  }

  if (id && data.documentName) {
    for (const pack of game.packs) {
      if (packDocumentName(pack) !== data.documentName) continue;
      const indexed = pack.index?.get?.(id);
      if (indexed || pack.index?.[id]) {
        return resolveCompendiumEntryUuid(pack, { ...indexed, _id: id, uuid: data.uuid });
      }
    }
  }
  return null;
}

export async function ensureSpotlightIndex(spotlight) {
  if (!spotlight?.rebuildIndex || !Array.isArray(spotlight.INDEX)) return null;
  const hasDocumentTerms = spotlight.INDEX.some((term) => !!term?.data?.documentName);
  if (spotlight.INDEX.length === 0 || !hasDocumentTerms) {
    console.log(`[${MODULE_ID}] Spotlight INDEX not ready on this client — forcing rebuildIndex()`);
    try {
      await spotlight.rebuildIndex();
    } catch (err) {
      console.error(`[${MODULE_ID}] rebuildIndex() failed`, err);
    }
  }
  return Array.isArray(spotlight.INDEX) ? spotlight.INDEX : null;
}

export async function spotlightCompendiumSearch(query, types, subtypes, limit, spotlight) {
  const splitQuery = parseCompendiumSearchQuery(query);
  if (!splitQuery) return { results: [] };
  const typeFilter = Array.isArray(types) && types.length > 0 ? new Set(types) : new Set(["Item"]);
  const subtypeFilter = Array.isArray(subtypes) && subtypes.length > 0
    ? new Set(subtypes.map((s) => String(s).toLowerCase()))
    : null;
  const max = Math.max(1, Math.min(Number(limit) || 30, 100));

  const index = await ensureSpotlightIndex(spotlight);
  if (!index?.length) return { results: [] };

  const results = [];
  const seen = new Set();
  const stripHtml = (s) => String(s ?? "").replace(/<[^>]*>/g, "").trim();

  for (const term of index) {
    if (results.length >= max) break;
    const docName = term?.data?.documentName;
    if (!docName || !typeFilter.has(docName)) continue;
    if (subtypeFilter) {
      const rawSubtype = term?.data?.type;
      if (!rawSubtype || !subtypeFilter.has(String(rawSubtype).toLowerCase())) continue;
    }
    const name = String(term?.name ?? "");
    if (!name || !compendiumNameMatchesQuery(name, term?.keywords, splitQuery, term)) continue;
    const uuid = resolveCompendiumUuidFromSpotlightTerm(term);
    if (!uuid) continue;
    const imgRaw = term?.img ?? term?.data?.img ?? null;
    pushCompendiumSearchResult(results, seen, max, {
      uuid,
      name,
      documentName: docName,
      pack: stripHtml(term?.description) || null,
      subtype: term?.data?.type ? String(term.data.type) : (term?.type ? String(term.type) : null),
      img: routeAssetPath(imgRaw)
    });
  }

  console.log(
    `[${MODULE_ID}] compendium.search via Spotlight: query="${splitQuery.join(" ")}"` +
    ` types=[${[...typeFilter].join(",")}]` +
    (subtypeFilter ? ` subtypes=[${[...subtypeFilter].join(",")}]` : "") +
    ` → ${results.length} hits (index size ${index.length})`
  );
  results.sort((a, b) => {
    const rank = (s) => {
      const t = String(s?.subtype ?? "").toLowerCase();
      if (t === "weapon") return 0;
      if (t === "equipment") return 1;
      if (t === "consumable") return 3;
      return 2;
    };
    const r = rank(a) - rank(b);
    if (r !== 0) return r;
    const demote = (p) => {
      const s = String(p ?? "").toLowerCase();
      return s.includes("world") || s.includes("ddb") ? 1 : 0;
    };
    return demote(a.pack) - demote(b.pack);
  });
  return { results };
}

/**
 * Search compendiums for documents matching `query`.
 *
 * @param {string} query     Substring matched case-insensitively against name.
 * @param {string[]} [types] Document types to include, e.g. ["Item"]. Default: ["Item"].
 * @param {number} [limit]   Max results to return. Default: 30.
 */
/**
 * Every compendium entry of a type, without a search term, sorted by name.
 * Feeds the race and class pickers, which have to show something before the
 * player types.
 */
export async function compendiumBrowse(types, subtypes, limit, user = null) {
  const found = await nativeCompendiumSearch(null, types, subtypes, limit ?? 100, user);
  found.results.sort((a, b) => String(a.name).localeCompare(String(b.name)));
  return found;
}

